CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'member',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS login_tokens(token TEXT PRIMARY KEY,email TEXT NOT NULL,name TEXT NOT NULL,ref TEXT,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL DEFAULT 1,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY,name TEXT NOT NULL,platform TEXT NOT NULL,url TEXT NOT NULL UNIQUE,own INTEGER NOT NULL DEFAULT 0,enabled INTEGER NOT NULL DEFAULT 1,cursor TEXT,external_id TEXT,last_sync TEXT,last_error TEXT);
CREATE TABLE IF NOT EXISTS videos(id TEXT PRIMARY KEY,source_id TEXT REFERENCES sources(id),platform TEXT NOT NULL,external_id TEXT NOT NULL,title TEXT NOT NULL,description TEXT DEFAULT '',url TEXT NOT NULL,thumbnail TEXT DEFAULT '',duration INTEGER DEFAULT 0,published_at TEXT,kind TEXT NOT NULL DEFAULT 'review' CHECK(kind IN ('video','live','review')),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','published','hidden')),category TEXT NOT NULL DEFAULT 'Conversaciones',featured INTEGER NOT NULL DEFAULT 0,UNIQUE(platform,external_id));
CREATE TABLE IF NOT EXISTS posts(id TEXT PRIMARY KEY,slug TEXT NOT NULL UNIQUE,title TEXT NOT NULL,excerpt TEXT DEFAULT '',body TEXT NOT NULL,category TEXT DEFAULT 'Comunidad',status TEXT NOT NULL DEFAULT 'draft',image TEXT DEFAULT '',download_url TEXT DEFAULT '',download_title TEXT DEFAULT '',updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS shares(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),video_id TEXT NOT NULL REFERENCES videos(id),created_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,video_id));
CREATE TABLE IF NOT EXISTS points(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),amount INTEGER NOT NULL,reason TEXT NOT NULL,event_key TEXT NOT NULL UNIQUE,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS points_user ON points(user_id);
CREATE INDEX IF NOT EXISTS videos_catalog ON videos(status,kind,published_at);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS donations(id TEXT PRIMARY KEY,amount INTEGER NOT NULL CHECK(amount>0),note TEXT DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS classifications(fingerprint TEXT PRIMARY KEY,video_id TEXT NOT NULL,model TEXT NOT NULL,response TEXT NOT NULL,input_tokens INTEGER NOT NULL DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS classifications_video ON classifications(video_id);
CREATE TABLE IF NOT EXISTS media_labels(video_id TEXT PRIMARY KEY,fingerprint TEXT NOT NULL,category TEXT NOT NULL,relevance TEXT NOT NULL,response TEXT NOT NULL,model TEXT NOT NULL,input_tokens INTEGER NOT NULL DEFAULT 0,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS editorial_overrides(video_id TEXT PRIMARY KEY);
